def classify_fill(c):
    """Fallback for colours outside the known palette."""
    if not c or not c.startswith("#") or len(c) != 7:
        return "#ffffff"
    r, g, b = hex2rgb(c)
    mx, mn = max(r, g, b), min(r, g, b)
    l = (mx + mn) / 2
    s = 0 if mx == mn else (mx - mn) / (1 - abs(2 * l - 1) or 1)
    if l < 0.32:
        return INK
    if s < 0.12:
        return "#ffffff" if l > 0.9 else "#f5f5f5"
    # hue
    if mx == r:
        h = (60 * ((g - b) / (mx - mn)) + 360) % 360
    elif mx == g:
        h = 60 * ((b - r) / (mx - mn)) + 120
    else:
        h = 60 * ((r - g) / (mx - mn)) + 240
    if 60 <= h < 180:
        return "#e5edd6"          # green/teal -> sage
    if h < 250:
        return "#f2d4cf"          # warm/red/orange -> blush
    return "#f5f5f5"              # blue/purple -> neutral cell

